    typeof value.title === 'string' && value.title.length > 0 && value.title.length <= 160 &&
    /^[0-9a-f]{40}$/.test(value.gitBlob ?? '') && /^[0-9a-f]{64}$/.test(value.sha256 ?? '') &&
    Number.isSafeInteger(value.bytes) && value.bytes > 0 && value.bytes <= 1024 * 1024,
